import{_ as i,a0 as r,w as m,s,ao as n,I as a,x as p,a1 as f,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"如何使用ffmpeg从视频中提取图片 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用ffmpeg从视频中提取图片 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用ffmpeg从视频中提取图片 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用ffmpeg从视频中提取图片 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/20140607 How To Extract Images From Videos Using ffmpeg","title":"如何使用ffmpeg从视频中提取图片","tag":"201406","desc":""},"relativePath":"201406/20140607 How To Extract Images From Videos Using ffmpeg.md","filePath":"[post].md"}'),l={name:"201406/20140607 How To Extract Images From Videos Using ffmpeg.md"};function g(d,e,u,x,T,w){const t=r("Link");return m(),s("div",null,[e[11]||(e[11]=n(`<h1 id="如何使用ffmpeg从视频中提取图片" tabindex="-1">如何使用ffmpeg从视频中提取图片 <a class="header-anchor" href="#如何使用ffmpeg从视频中提取图片" aria-label="Permalink to “如何使用ffmpeg从视频中提取图片”">​</a></h1><p>你曾想过从一个视频文件中提取图片吗？在Linux下就可以，在这个教程中我将使用ffmpeg来从视频中获取图片。</p><h3 id="什么是ffmpeg-what-is-ffmpeg" tabindex="-1">什么是ffmpeg？What is ffmpeg? <a class="header-anchor" href="#什么是ffmpeg-what-is-ffmpeg" aria-label="Permalink to “什么是ffmpeg？What is ffmpeg?”">​</a></h3><p>ffmpeg是一个非常有用的命令行程序，它可以用来转码媒体文件。它是领先的多媒体框架FFmpeg的一部分，其有很多功能，比如解码、编码、转码、混流、分离、转化为流、过滤以及播放几乎所有的由人和机器创建的媒体文件。</p><p>在这个框架中包含有各种工具，每一个用于完成特定的功能。例如，ffserver能够将多媒体文件转化为用于实时广播的流，ffprobe用于分析多媒体流，ffplay可以当作一个简易的媒体播放器，<strong>ffmpeg</strong>则能够转换多媒体文件格式。</p><p>如果你感兴趣，以下列出的是FFmpeg框架中包含的开发者库：</p><ul><li>libavutil是一个包含简化编程功能的库，其中包括随机数生成器，数据结构，数学代码，核心多媒体工具等更多东西。</li><li>libavcodec是一个包含音频/视频解码器和编码器的库。</li><li>libavformat是一个包含了多媒体格式的分离器和混流器的库。</li><li>libavdevice是一个包含输入输出设备的库，用于捕捉和渲染很多来自常用的多媒体输入/输出软件框架的数据，包括Video4Linux，Video4Linux2，VfW和ALSA。</li><li>libavfilter是一个包含媒体过滤器的库。</li><li>libswscale是一个用于执行高度优化的图像缩放和颜色空间/像素格式转换操作的库。</li><li>libswresample是一个用于执行高度优化的音频重采样，重新矩阵和取样格式转换操作的库。</li></ul><p><strong>注意</strong>：ffmpeg和FFmpeg不是同一个东西。FFmpeg是框架，而ffmpeg是一个其中的一个功能。</p><h3 id="开始行动" tabindex="-1">开始行动 <a class="header-anchor" href="#开始行动" aria-label="Permalink to “开始行动”">​</a></h3><p>如果你想跟着教程做，你需要在你的linux机中安装ffmpeg命令行功能。Ubuntu用户可以在终端运行以下命令轻松安装ffmpeg功能。</p><pre><code>sudo apt-get install ffmpeg
</code></pre><p>Fedora用户可以从源中直接安装ffmpeg。</p><pre><code>yum install ffmpeg
</code></pre><p>或者你可以编译源代码。在你使用源代码编译并安装它之前，你需要从官网上下载源代码，使用以下命令。</p><pre><code>wget http://www.ffmpeg.org/releases/ffmpeg-2.2.3.tar.bz2
</code></pre><p>用下面命令解压文档。</p><pre><code>tar -xvjf ffmpeg-2.2.3.tar.bz2
</code></pre><p>文档解压完成后进入解压后的目录运行以下命令。</p><pre><code>./configure
make
</code></pre><p>编译完成后运行下面的命令安装ffmpeg。</p><pre><code>su -c &#39;make install&#39;
</code></pre><p>全部的事情并没有完成，而你将要做的所有事就是在终端键入一些命令而且将能够从任何视频文件中抓取图片。</p><p>在做之后的步骤前，确保你在想要提取图片的视频文件的目录下。使用cd命令切换到正确的目录。教程中我使用的视频在我的桌面上，我用以下命令将目录切换到我的桌面。</p><pre><code>cd /home/oltjano/Desktop
</code></pre><p>之后我使用以下命令从视频中提取图片。</p><pre><code>ffmpeg -i &quot;你是我的小呀小苹果儿.mp4&quot; -r 1 -q:v 2 -f image2 image-3%d.jpeg
</code></pre><p><strong>-i</strong>选项用来获取输入文件，在这里是视频文件名<strong>你是我的小呀小苹果儿.mp4</strong>，-r选项设置每秒提取图片的帧数。我想要每秒提取一帧。</p><p>之后有一个重要的选项是-q:v，应该留意这个选项并且我很喜欢用它，它用来设置提取到的图片质量。我总是设置值为2来从视频中获取高质量图片。</p><hr>`,29)),a("p",null,[e[1]||(e[1]=p("via: ",-1)),f(t,{href:"http://www.unixmen.com/extract-images-videos-using-ffmpeg/"},{default:o(()=>[...e[0]||(e[0]=[p("http://www.unixmen.com/extract-images-videos-using-ffmpeg/",-1)])]),_:1})]),a("p",null,[e[4]||(e[4]=p("译者：",-1)),f(t,{href:"https://github.com/linuhap"},{default:o(()=>[...e[2]||(e[2]=[p("linuhap",-1)])]),_:1}),e[5]||(e[5]=p(" 校对：",-1)),f(t,{href:"https://github.com/wxy"},{default:o(()=>[...e[3]||(e[3]=[p("wxy",-1)])]),_:1})]),a("p",null,[e[8]||(e[8]=p("本文由 ",-1)),f(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[6]||(e[6]=[p("LCTT",-1)])]),_:1}),e[9]||(e[9]=p(" 原创翻译，",-1)),f(t,{href:"http://linux.cn/"},{default:o(()=>[...e[7]||(e[7]=[p("Linux中国",-1)])]),_:1}),e[10]||(e[10]=p(" 荣誉推出",-1))])])}const v=i(l,[["render",g]]);export{h as __pageData,v as default};
